type Product = { id: string; name: string; categoryId: string; priceCents: number };
type CatalogueQuestion = {
  query(input: { question: string; filter: { categoryId: string }; topK: number }): Promise<{ answer: string }>;
};

export async function answerCategoryQuestion(
  retriever: CatalogueQuestion,
  categoryId: string,
  question: string,
): Promise<string> {
  const result = await retriever.query({
    question,
    filter: { categoryId },
    topK: 5,
  });
  return result.answer;
}
